// Crypto glossary (/glossary, /glossary/<slug>), 2026-10-13. Entry-safe helpers only: the router and the route module
// cache import this file, so it must stay tiny (no term table here; that is glossary-terms.js in the route chunk).
//
// Content modules (generated by scripts/build-glossary-data.mjs):
//   glossary-index-<locale>.js       hub list (slug, name, one-line definition, category)
//   glossary-shard-<locale>-<n>.js   full term pages, GLOSSARY_SHARDS shards per locale, picked by glossaryShard(slug)
//   glossary-links-<locale>.js       name forms for auto-linking terms in news articles and academy transcripts

export const GLOSSARY_PATH = "/glossary";
// Search editions written natively (not translated). Other UI locales render the English entries as noindex,follow.
export const GLOSSARY_INDEX_LOCALES = Object.freeze(["en", "zh-Hans", "es", "pt-BR", "tr", "vi", "id", "ja", "ko"]);
export const GLOSSARY_SHARDS = 16;

export const glossaryContentLocale = (locale) => (GLOSSARY_INDEX_LOCALES.includes(locale) ? locale : "en");
const fileLocale = (locale) => glossaryContentLocale(locale).toLowerCase();
/** Stable shard of a term slug (FNV-1a), so the browser can preload a term's module without the term table. */
export function glossaryShard(slug) {
  let hash = 0x811c9dc5;
  for (const ch of String(slug)) { hash ^= ch.charCodeAt(0); hash = Math.imul(hash, 0x01000193) >>> 0; }
  return hash % GLOSSARY_SHARDS;
}
export const glossaryIndexModulePath = (locale) => `./data/glossary-index-${fileLocale(locale)}.js`;
export const glossaryShardModulePath = (locale, slug) => `./data/glossary-shard-${fileLocale(locale)}-${glossaryShard(slug)}.js`;
export const glossaryLinksModulePath = (locale) => `./data/glossary-links-${fileLocale(locale)}.js`;
export const glossaryTermPath = (slug) => `${GLOSSARY_PATH}/${slug}`;

/** { kind: "hub" } | { kind: "term", slug } | { kind: "missing" } for /glossary paths, null elsewhere. */
export function parseGlossaryPath(pathname) {
  const path = String(pathname || "").split(/[?#]/)[0].replace(/\/+$/, "") || "/";
  if (path === GLOSSARY_PATH) return { kind: "hub" };
  const match = path.match(/^\/glossary\/([a-z0-9][a-z0-9-]{0,60})$/);
  if (match) return { kind: "term", slug: match[1] };
  return path.startsWith(`${GLOSSARY_PATH}/`) ? { kind: "missing" } : null;
}
// Footer label (entry: keep tiny). Other UI locales link the English glossary under the English label.
const NAV = { en: "Glossary", "zh-Hans": "术语表", es: "Glosario", "pt-BR": "Glossário", tr: "Sözlük", vi: "Thuật ngữ", id: "Glosarium", ja: "用語集", ko: "용어 사전" };
export const glossaryNavLabel = (locale) => NAV[locale] || NAV.en;
